create or replace function nexus_private.workflow_chat_instant(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare text_value text;
begin
  if jsonb_typeof(value) is distinct from 'string' then return false; end if;
  text_value:=value #>> '{}';
  return text_value ~ '^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$';
end $$;

create or replace function nexus_private.workflow_chat_analysis(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare field text; claims jsonb; claim jsonb; source jsonb;
begin
  if jsonb_typeof(value) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(value))<>6
    or not value ?& array['facts','relationships','hypotheses','missingEvidence','generatedAt','evidenceVersion']
    or not nexus_private.workflow_chat_instant(value->'generatedAt')
    or jsonb_typeof(value->'evidenceVersion') is distinct from 'string'
    or length(value->>'evidenceVersion')<1 then return false; end if;
  foreach field in array array['facts','relationships','hypotheses','missingEvidence'] loop
    claims:=value->field;
    if jsonb_typeof(claims) is distinct from 'array' then return false; end if;
    if jsonb_array_length(claims)>100 then return false; end if;
    for claim in select item from jsonb_array_elements(claims) item loop
      if jsonb_typeof(claim) is distinct from 'object' then return false; end if;
      if (select count(*) from jsonb_object_keys(claim))<>2 or not claim ?& array['text','sourceIds']
        or jsonb_typeof(claim->'text') is distinct from 'string'
        or nexus_private.workflow_utf16_length(claim->>'text') not between 1 and 1000
        or jsonb_typeof(claim->'sourceIds') is distinct from 'array' then return false; end if;
      if jsonb_array_length(claim->'sourceIds')>100 then return false; end if;
      for source in select item from jsonb_array_elements(claim->'sourceIds') item loop
        if jsonb_typeof(source) is distinct from 'string' or length(source #>> '{}')<1 then return false; end if;
      end loop;
    end loop;
  end loop;
  return true;
end $$;

create or replace function nexus_private.workflow_chat_scope(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare branch jsonb;
begin
  if value='null'::jsonb then return true; end if;
  if jsonb_typeof(value) is distinct from 'object' then return false; end if;
  if not value ?& array['region','date']
    or exists(select 1 from jsonb_object_keys(value) k where k not in('region','date','branchIds'))
    or jsonb_typeof(value->'region') is distinct from 'string'
    or nexus_private.workflow_utf16_length(value->>'region') not between 1 and 40
    or jsonb_typeof(value->'date') is distinct from 'string'
    or not nexus_private.workflow_chat_instant(to_jsonb((value->>'date')||'T00:00:00Z')) then return false; end if;
  if value ? 'branchIds' then
    if jsonb_typeof(value->'branchIds') is distinct from 'array' then return false; end if;
    if jsonb_array_length(value->'branchIds')>12 then return false; end if;
    for branch in select item from jsonb_array_elements(value->'branchIds') item loop
      if jsonb_typeof(branch) is distinct from 'string' then return false; end if;
    end loop;
  end if;
  return true;
end $$;

-- Explicit optional fields are checked when present; absent V1 fields stay absent.
create or replace function nexus_private.workflow_chat_body_valid(table_name text,body jsonb,definition jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare field text; value jsonb;
begin
  if jsonb_typeof(body) is distinct from 'object' then return false; end if;
  if exists(select 1 from jsonb_object_keys(body) k where not (definition->'bodyFields') ? k)
    or not coalesce(nexus_private.workflow_identifier(body->'id'),false)
    or not coalesce(nexus_private.workflow_identifier(body->'actorId'),false) then return false; end if;
  if body ? 'rowVersion' then
    if jsonb_typeof(body->'rowVersion') is distinct from 'number'
      or body->>'rowVersion' !~ '^[1-9][0-9]*$' then return false; end if;
    if (body->>'rowVersion')::numeric>9007199254740991 then return false; end if;
  end if;
  if table_name='conversations' then
    if body ? 'title' and (jsonb_typeof(body->'title') is distinct from 'string'
      or nexus_private.workflow_utf16_length(body->>'title') not between 1 and 120
      or body->>'title' is distinct from btrim(body->>'title',U&'\0009\000A\000B\000C\000D \00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')) then return false; end if;
    if body ? 'pinned' and jsonb_typeof(body->'pinned') is distinct from 'boolean' then return false; end if;
    foreach field in array array['pinnedAt','archivedAt','createdAt','updatedAt'] loop
      if body ? field and not (field in('pinnedAt','archivedAt','createdAt') and body->field='null'::jsonb)
        and not nexus_private.workflow_chat_instant(body->field) then return false; end if;
    end loop;
    if body ? 'lastScope' and not nexus_private.workflow_chat_scope(body->'lastScope') then return false; end if;
    if body ? 'lastDashboardId' and body->'lastDashboardId'<>'null'::jsonb
      and not nexus_private.workflow_identifier(body->'lastDashboardId') then return false; end if;
    if body ? 'lastAnalysis' and not nexus_private.workflow_chat_analysis(body->'lastAnalysis') then return false; end if;
  elsif table_name='conversation_messages' then
    if not coalesce(nexus_private.workflow_identifier(body->'conversationId'),false)
      or jsonb_typeof(body->'role') is distinct from 'string' or body->>'role' not in('user','assistant')
      or jsonb_typeof(body->'text') is distinct from 'string' or nexus_private.workflow_utf16_length(body->>'text')>100000
      or jsonb_typeof(body->'mode') is distinct from 'string' or body->>'mode' not in('live_ai','scripted_demo')
      or jsonb_typeof(body->'modeRevision') is distinct from 'number' then return false; end if;
    if (body->>'modeRevision')::numeric not between 0 and 9007199254740991 or trunc((body->>'modeRevision')::numeric)<>(body->>'modeRevision')::numeric
      or not nexus_private.workflow_chat_instant(body->'createdAt') then return false; end if;
    foreach field in array array['turnId','sessionId','pendingActionId','receiptId'] loop
      if body ? field and not nexus_private.workflow_identifier(body->field) then return false; end if;
    end loop;
    if body ? 'pendingActionIds' then
      value:=body->'pendingActionIds';
      if jsonb_typeof(value) is distinct from 'array' then return false; end if;
      if jsonb_array_length(value)>100
        or exists(select 1 from jsonb_array_elements(value) item where not nexus_private.workflow_identifier(item))
        or (select count(*) from jsonb_array_elements(value))<>(select count(distinct item) from jsonb_array_elements(value) item) then return false; end if;
    end if;
    if body ? 'analysis' and not nexus_private.workflow_chat_analysis(body->'analysis') then return false; end if;
  else return false;
  end if;
  return true;
exception when invalid_text_representation or numeric_value_out_of_range then return false;
end $$;

create or replace function nexus_private.workflow_chat_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare d jsonb;
begin
  select definition into strict d from nexus_private.workflow_manifest where table_name=tg_table_name;
  if not nexus_private.workflow_chat_body_valid(tg_table_name,new.payload,d) then
    raise exception 'Invalid persisted conversation body' using errcode='23514';
  end if;
  return new;
end $$;

-- Frozen predecessor guard with one bounded createdAt enrichment exception.
-- All other immutable-field, version, marker, relationship and history guards remain exact.
create or replace function nexus_private.workflow_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare d jsonb; b jsonb; old_b jsonb; row_json jsonb; typed jsonb:='{}'; c jsonb; f jsonb; child jsonb; v jsonb; discriminator jsonb; equality jsonb;
  field text; old_state text; new_state text; target_count integer:=0; protected boolean;
begin
  select definition into strict d from nexus_private.workflow_manifest where table_name=tg_table_name;
  if tg_op='DELETE' then
    if tg_table_name='mock_tickets' and (to_jsonb(old)->>'legacy_assignee_quarantined'='1'
      or to_jsonb(old)->>'assignee_id' is not null
      or (to_jsonb(old)->>'workflow_contract_version' is null and to_jsonb(old)->>'employee_assignee_id' is null)) then
      raise exception 'Legacy profile ticket is quarantined' using errcode='23514';
    end if;
    if tg_table_name='audit_events' or (tg_table_name='action_executions' and (to_jsonb(old)->'payload'->>'status') in ('verified_success','failed','denied')) then raise exception 'Immutable legacy history' using errcode='23514'; end if;
    if d->>'storage'<>'shared' and (d->>'storage'<>'mixed' or to_jsonb(old)->>'workflow_contract_version'='2') then raise exception 'Workflow history cannot be deleted' using errcode='23514'; end if;
    return old;
  end if;
  row_json:=to_jsonb(new); b:=row_json->(d->>'bodyColumn');
  if jsonb_typeof(b)<>'object' or jsonb_typeof(b->'id')<>'string' or b->>'id' is distinct from new.id then raise exception 'Invalid workflow body identity' using errcode='23514'; end if;
  protected:=d->>'storage'<>'mixed' or coalesce(row_json->>'workflow_contract_version'='2',false);
  if tg_table_name='mock_tickets' then
    if tg_op='INSERT' and (row_json->>'legacy_assignee_quarantined' is distinct from '0' or row_json->>'assignee_id' is not null) then
      raise exception 'Legacy profile assignee cannot be inserted' using errcode='23514';
    end if;
    if tg_op='UPDATE' then
      if row_json->'legacy_assignee_quarantined' is distinct from to_jsonb(old)->'legacy_assignee_quarantined' then
        raise exception 'Immutable ticket quarantine' using errcode='23514';
      end if;
      if to_jsonb(old)->>'legacy_assignee_quarantined'='1' or to_jsonb(old)->>'assignee_id' is not null
        or (to_jsonb(old)->>'workflow_contract_version' is null and to_jsonb(old)->>'employee_assignee_id' is null) then
        raise exception 'Legacy profile ticket is quarantined' using errcode='23514';
      end if;
      if row_json->>'assignee_id' is not null or b->>'assigneeId' is distinct from to_jsonb(old)->>'employee_assignee_id' then
        raise exception 'Immutable ticket employee assignee' using errcode='23514';
      end if;
    end if;
    if not exists(select 1 from public.employees e where e.id=b->>'assigneeId') then
      raise exception 'Ticket assignee must be an employee' using errcode='23514';
    end if;
  end if;
  if tg_op='UPDATE' then
    old_b:=to_jsonb(old)->(d->>'bodyColumn');
    if d->>'storage'='mixed' and row_json->'workflow_contract_version' is distinct from to_jsonb(old)->'workflow_contract_version' then raise exception 'Immutable workflow marker' using errcode='23514'; end if;
  end if;
  if not protected then
    if tg_op='UPDATE' and (tg_table_name='audit_events' or (tg_table_name='action_executions' and old_b->>'status' in ('verified_success','failed','denied'))) then raise exception 'Immutable legacy history' using errcode='23514'; end if;
    for discriminator in select value from jsonb_array_elements(d->'markerlessV2Discriminators') loop
      v:=b #> string_to_array(discriminator->>'path','.');
      if (coalesce((discriminator->>'presence')::boolean,false) and v is not null) or ((not discriminator ? 'equals') and v is not null and v<>'null'::jsonb) or (discriminator ? 'equals' and v=discriminator->'equals') then raise exception 'V2 row requires protected marker' using errcode='23514'; end if;
    end loop;
    if tg_table_name<>'mock_tickets' then return new; end if;
  end if;
  for equality in select value from jsonb_array_elements(d->'projectionEqualities') loop
    if (b #> string_to_array(equality->>'leftPath','.')) is distinct from (b #> string_to_array(equality->>'rightPath','.')) then raise exception 'Inconsistent workflow reference projection' using errcode='23514'; end if;
  end loop;
  if tg_table_name in ('pending_actions','action_executions') and b->>'contractVersion' is distinct from '2' then raise exception 'Protected workflow contract version required' using errcode='23514'; end if;
  if tg_table_name='pending_actions' and (b #>> '{policy,id}' is null or b #>> '{policy,version}' is null or b #>> '{policy,digest}' is null) then raise exception 'Missing workflow policy reference' using errcode='23514'; end if;
  if tg_op='INSERT' then
    if (d->>'storage'='shared' or (tg_table_name='mock_tickets' and not protected)) and new.row_version is null then new.row_version:=1; end if;
    if new.row_version is distinct from 1 then raise exception 'Invalid workflow insertion version' using errcode='23514'; end if;
  else
    if nexus_private.workflow_legacy_read_only(old_b,d) then raise exception 'Legacy workflow data is read-only' using errcode='23514'; end if;
    -- SQLite permits a first write to an existing, non-quarantined employee
    -- ticket whose V1 native version was NULL. Migration itself never fills it.
    if tg_table_name='mock_tickets' and not protected and old.row_version is null and new.row_version is null then new.row_version:=1; end if;
    if (d->>'storage'='shared' or (tg_table_name='mock_tickets' and not protected)) and new.row_version=old.row_version then new.row_version:=old.row_version+1; end if;
    if new.row_version is distinct from old.row_version+1
      and not (tg_table_name='mock_tickets' and not protected and old.row_version is null and new.row_version=1) then
      raise exception 'Invalid workflow conditional version' using errcode='23514';
    end if;
    for field in select jsonb_array_elements_text(d->'immutableFields') loop
      if b #> string_to_array(field,'.') is distinct from old_b #> string_to_array(field,'.')
        and not (tg_table_name='conversations' and field='createdAt' and (d->'bodyFields') ? 'lastAnalysis'
          and (old_b->'createdAt' is null or old_b->'createdAt'='null'::jsonb)
          and nexus_private.workflow_chat_instant(b->'createdAt')) then raise exception 'Immutable workflow field' using errcode='23514'; end if;
    end loop;
    if exists(select 1 from jsonb_array_elements(d->'foreignKeys') x where x ? 'tagField') and b->'ref' is distinct from old_b->'ref' then raise exception 'Immutable workflow target reference' using errcode='23514'; end if;
    if coalesce((d->>'appendOnly')::boolean,false) and b is distinct from old_b then raise exception 'Append-only workflow history' using errcode='23514'; end if;
    if tg_table_name='pending_actions' and (b-'status'-'rowVersion') is distinct from (old_b-'status'-'rowVersion') then raise exception 'Immutable workflow approval' using errcode='23514'; end if;
    old_state:=nexus_private.workflow_state(old_b,d); new_state:=nexus_private.workflow_state(b,d);
    for field in select jsonb_array_elements_text(coalesce(d->'terminalImmutableFields'->old_state,'[]'::jsonb)) loop
      if b #> string_to_array(field,'.') is distinct from old_b #> string_to_array(field,'.') then raise exception 'Immutable terminal workflow field' using errcode='23514'; end if;
    end loop;
    if tg_table_name='action_executions' and old_state in ('verified_success','already_completed','failed','denied','stale') and b is distinct from old_b then raise exception 'Immutable historical receipt' using errcode='23514'; end if;
    if tg_table_name='action_targets' and old_state in ('verified','failed') and b is distinct from old_b then raise exception 'Immutable target proof' using errcode='23514'; end if;
    if old_state is distinct from new_state and d->'permittedTransitions'<>'{}'::jsonb and not coalesce((d->'permittedTransitions'->old_state) ? new_state,false) then
      if tg_table_name<>'incidents' or not exists(select 1 from public.action_executions r join public.pending_actions a on a.id=r.payload->>'actionId' join public.profiles p on p.id=a.payload->>'actorId' join public.sessions s on s.id=a.payload->>'sessionId' where r.workflow_contract_version is null and a.workflow_contract_version is null and b->>'operationKey'=r.id||':artifact' and r.payload->>'kind'='demo_update' and r.payload->>'status'='pending' and a.payload #>> '{payload,scenario}'='baseline' and a.payload->>'status'='claimed' and p.payload->>'active'='true' and s.profile_id=p.id and (p.payload->'permissions') ? 'demo.update') then raise exception 'Invalid workflow transition' using errcode='23514'; end if;
    end if;
  end if;
  if b ? 'rowVersion' and (jsonb_typeof(b->'rowVersion')<>'number' or b->>'rowVersion' !~ '^[0-9]+$' or (b->>'rowVersion')::bigint<>new.row_version) then raise exception 'Inconsistent workflow body version' using errcode='23514'; end if;
  if d->>'storage'<>'shared' and exists(select 1 from jsonb_object_keys(b) k where not (d->'bodyFields') ? k) then raise exception 'Unsupported workflow body field' using errcode='23514'; end if;
  for child in select value from jsonb_array_elements(d->'normalizedChildren') loop
    v:=b #> string_to_array(child->>'arrayBodyField','.');
    if coalesce((child->>'immutable')::boolean,false) and v is null then continue; end if;
    if jsonb_typeof(v) is distinct from 'array' then raise exception 'Invalid normalized workflow scope' using errcode='23514'; end if;
    if exists(select 1 from jsonb_array_elements(v) x where jsonb_typeof(x)<>'string') or (select count(*) from jsonb_array_elements(v))<>(select count(distinct value) from jsonb_array_elements(v)) then raise exception 'Invalid normalized workflow scope' using errcode='23514'; end if;
  end loop;
  for c in select value from jsonb_array_elements(d->'columns') loop
    if coalesce((c->>'legacyOnly')::boolean,false) then continue; end if;
    if coalesce((c->>'external')::boolean,false) then
      v:=row_json->(c->>'column');
      if tg_op='UPDATE' and v is distinct from to_jsonb(old)->(c->>'column') then raise exception 'Immutable workflow key projection' using errcode='23514'; end if;
    else v:=nexus_private.workflow_value(b,c); end if;
    if v='null'::jsonb then
      if not (c->>'nullable')::boolean then raise exception 'Missing workflow typed field' using errcode='23514'; end if;
    elsif (c->>'type'='text' and jsonb_typeof(v)<>'string') or (c->>'type'='boolean' and jsonb_typeof(v)<>'boolean')
      or (c->>'type' in ('integer','real') and jsonb_typeof(v)<>'number') then raise exception 'Invalid workflow typed field' using errcode='23514'; end if;
    if c->>'type'='integer' and v<>'null'::jsonb and (v::text !~ '^[0-9]+$') then raise exception 'Invalid workflow integral value' using errcode='23514'; end if;
    if c->>'type'='integer' and v<>'null'::jsonb and c->>'column' ~ '(version|attempt|quantity)$' and v::text='0' then raise exception 'Invalid workflow positive value' using errcode='23514'; end if;
    -- Explicit column tampering is rejected; omitted/stale legacy projections are derived.
    if row_json->(c->>'column') is not null and row_json->(c->>'column')<>'null'::jsonb
      and row_json->(c->>'column') is distinct from v
      and (tg_op='INSERT' or row_json->(c->>'column') is distinct from to_jsonb(old)->(c->>'column')) then raise exception 'Inconsistent workflow SQL projection' using errcode='23514'; end if;
    typed:=typed||jsonb_build_object(c->>'column',v);
  end loop;
  new:=jsonb_populate_record(new,typed);
  new_state:=nexus_private.workflow_state(b,d);
  if d->'permittedTransitions'<>'{}'::jsonb and (new_state is null or not (d->'permittedTransitions') ? new_state) then raise exception 'Invalid workflow status' using errcode='23514'; end if;
  for f in select value from jsonb_array_elements(d->'foreignKeys') where value ? 'tagField' loop
    if (to_jsonb(new)->(f->>'column'))<>'null'::jsonb then target_count:=target_count+1; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(d->'foreignKeys') x where x ? 'tagField') then
    if target_count<>1 or b->>'entityType' is distinct from b #>> '{ref,table}' then raise exception 'Invalid workflow target reference' using errcode='23514'; end if;
  end if;
  if tg_table_name='share_scope_branches' and not exists(select 1 from public.dashboard_shares s,jsonb_array_elements_text(s.payload->'approvedBranchIds') x where s.id=b->>'shareId' and s.workflow_contract_version=2 and x=b->>'branchId') then raise exception 'Invalid workflow relationship' using errcode='23514'; end if;
  if tg_table_name='onboarding_requests' then
    foreach field in array array['manager','director'] loop
      v:=b->(field||'ApprovalEventId');
      if (v is null or v='null'::jsonb) then
        if (field='manager' and b->>'state' in ('director_approval_pending','director_approved','onboarding_in_progress','completed')) or (field='director' and b->>'state' in ('director_approved','onboarding_in_progress','completed')) then raise exception 'Missing onboarding approval proof' using errcode='23514'; end if;
      elsif not exists(select 1 from public.onboarding_approval_events e where e.id=b->>(field||'ApprovalEventId') and e.request_id=new.id and e.stage=field and e.lifecycle_id=b->>'lifecycleId' and e.actor_identity_id=b->>(field||'IdentityId')) then raise exception 'Invalid onboarding approval proof' using errcode='23514'; end if;
    end loop;
  end if;
  if tg_table_name='action_idempotency_roots' and exists(select 1 from public.action_executions e where e.id=b->>'activeExecutionId' and e.workflow_contract_version=2 and e.root_id<>new.id) then raise exception 'Invalid workflow execution root' using errcode='23514'; end if;
  if tg_table_name='action_executions' and exists(select 1 from public.action_idempotency_roots r where r.active_execution_id=new.id and r.id<>(to_jsonb(new)->>'root_id')) then raise exception 'Invalid workflow execution root' using errcode='23514'; end if;
  if tg_table_name='policy_acknowledgement_tasks' and not exists(select 1 from public.policy_documents p where p.id=b->>'policyDocumentId' and p.version=b->>'policyVersion') then raise exception 'Invalid workflow policy reference' using errcode='23514'; end if;
  if tg_table_name='simulated_deliveries' and not exists(select 1 from public.dashboard_shares s where s.id=b->>'shareId' and s.workflow_contract_version=2 and s.recipient_identity_id=b->>'recipientIdentityId' and s.payload->>'channel'=b->>'channel' and s.execution_id=b->>'executionId') then raise exception 'Invalid workflow delivery reference' using errcode='23514'; end if;
  perform nexus_private.workflow_completeness_guard(tg_table_name,b,old_b,d,tg_op,new.row_version,case when tg_op='UPDATE' then old.row_version else null end);
  return new;
end $$;

do $forward$
declare item record; predecessor_digest text; step_digest text; installed_digest text;
  saved_meta text; saved_ledger text; changed boolean; existed boolean; colname text; field text;
begin
  -- Full predecessor parity is checked using the predecessor's own JSONB MD5 algorithm.
  select md5(string_agg(table_name||definition::text,E'\n' order by table_name)) into predecessor_digest from pg_temp.workflow_chat_predecessor;
  select md5(string_agg(table_name||definition::text,E'\n' order by table_name)) into step_digest from pg_temp.workflow_chat_manifest;
  if (select definition_digest from nexus_private.workflow_projection_migrations where id='202610030002_workflow_projection_completeness') is distinct from predecessor_digest then
    raise exception 'Workflow conversation requires the frozen completeness ledger' using errcode='23514';
  end if;
  select definition_digest into installed_digest from nexus_private.workflow_projection_migrations where id='202610040001_workflow_conversation_persistence';
  if installed_digest is not null and installed_digest<>step_digest then raise exception 'Workflow conversation manifest changed without a new schema version' using errcode='23514'; end if;
  for item in
    select c.oid,c.relowner,n.nspname,c.relname from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    where (n.nspname='public' and c.relname in('appmeta','conversations','conversation_messages'))
      or (n.nspname='nexus_private' and c.relname in('workflow_manifest','workflow_projection_migrations'))
    order by case when c.relname='appmeta' then 0 else 1 end,n.nspname,c.relname
  loop
    if not pg_catalog.pg_has_role(current_user,item.relowner,'USAGE') and not (select rolsuper from pg_catalog.pg_roles where rolname=current_user) then
      raise exception 'Workflow conversation requires table ownership' using errcode='42501';
    end if;
    execute format('lock table %I.%I in access exclusive mode',item.nspname,item.relname);
  end loop;
  -- Reread ledgers under the locks; concurrent private metadata cannot escape the fence.
  if (select definition_digest from nexus_private.workflow_projection_migrations where id='202610030002_workflow_projection_completeness') is distinct from predecessor_digest
    or (select definition_digest from nexus_private.workflow_projection_migrations where id='202610040001_workflow_conversation_persistence') is distinct from installed_digest then
    raise exception 'Workflow conversation ledger changed while acquiring locks' using errcode='23514';
  end if;
  if exists(select 1 from pg_temp.workflow_chat_predecessor p full join nexus_private.workflow_manifest m using(table_name)
    left join pg_temp.workflow_chat_manifest n using(table_name)
    where p.table_name is null or m.table_name is null
      or m.definition is distinct from case when installed_digest is not null and n.table_name is not null then n.definition else p.definition end) then
    raise exception 'Workflow conversation preceding manifest does not match its ledger' using errcode='23514';
  end if;
  if exists(select 1 from pg_temp.workflow_chat_manifest m cross join (values('workflow_guard'),('nexus_revision')) required(trigger_name)
    left join pg_catalog.pg_trigger t on t.tgrelid=format('public.%I',m.table_name)::regclass and t.tgname=required.trigger_name
    where t.oid is null or t.tgenabled not in('O','A')) then raise exception 'Workflow conversation requires active preceding guards' using errcode='23514'; end if;
  if (select workflow_adapter_write from public.appmeta where singleton=1)<>0 then raise exception 'Workflow conversation found an active adapter write' using errcode='23514'; end if;
  select to_jsonb(a)::text into strict saved_meta from public.appmeta a where singleton=1;
  select coalesce(string_agg(id||':'||definition_digest,E'\n' order by id),'') into saved_ledger from nexus_private.workflow_projection_migrations;
  insert into pg_temp.workflow_chat_state values(saved_meta,saved_ledger,installed_digest is not null,step_digest);
  for item in select table_name,definition from pg_temp.workflow_chat_manifest order by table_name loop
    execute format('select exists(select 1 from public.%I where not nexus_private.workflow_chat_body_valid($1,payload,$2))',item.table_name) into changed using item.table_name,item.definition;
    if changed then raise exception 'Workflow conversation contains incompatible historical bodies' using errcode='23514'; end if;
    execute format('insert into pg_temp.workflow_chat_rows select %L,id,payload::text,row_version,to_jsonb(t) from public.%I t',item.table_name,item.table_name);
  end loop;
  if installed_digest is null then
    if exists(select 1 from pg_catalog.pg_trigger t where t.tgrelid in('public.conversations'::regclass,'public.conversation_messages'::regclass)
      and not t.tgisinternal and t.tgenabled<>'D' and t.tgname not in('workflow_guard','workflow_children','nexus_revision')) then
      raise exception 'Workflow conversation cannot suspend an unknown application trigger' using errcode='23514';
    end if;
    insert into pg_temp.workflow_chat_modes select tgrelid,tgname,tgenabled from pg_catalog.pg_trigger
      where tgrelid in('public.conversations'::regclass,'public.conversation_messages'::regclass) and not tgisinternal
        and tgname in('workflow_guard','workflow_children','nexus_revision');
    for item in select * from pg_temp.workflow_chat_modes loop execute format('alter table %s disable trigger %I',item.table_oid::regclass,item.trigger_name); end loop;
  end if;
  foreach colname in array array['turn_id','session_id'] loop
    field:=case colname when 'turn_id' then 'turnId' else 'sessionId' end;
    select exists(select 1 from pg_catalog.pg_attribute where attrelid='public.conversation_messages'::regclass and attname=colname and attnum>0 and not attisdropped) into existed;
    if existed then
      if exists(select 1 from pg_catalog.pg_attribute a where a.attrelid='public.conversation_messages'::regclass and a.attname=colname
        and (a.atttypid<>'text'::regtype or a.attnotnull or a.attgenerated<>'' or a.atthasdef)) then raise exception 'Workflow conversation native identity has an incompatible definition' using errcode='23514'; end if;
      execute format('select exists(select 1 from public.conversation_messages where %I is distinct from payload->>$1)',colname) into changed using field;
      if changed then raise exception 'Workflow conversation contains contradictory native identity' using errcode='23514'; end if;
    elsif installed_digest is not null then raise exception 'Workflow conversation installed column is missing' using errcode='23514';
    else
      execute format('alter table public.conversation_messages add column %I text',colname);
      execute format('update public.conversation_messages set %I=payload->>$1',colname) using field;
    end if;
  end loop;
  if installed_digest is null then
    -- Sequential backfills can queue deferred native FK checks even when their
    -- keys are unchanged. Validate them before DDL; never disable internal guards.
    set constraints all immediate;
    update nexus_private.workflow_manifest m set definition=n.definition from pg_temp.workflow_chat_manifest n where m.table_name=n.table_name;
    create index wf_conversation_messages_turn_id_lookup on public.conversation_messages(turn_id,id);
    create index wf_conversation_messages_session_id_lookup on public.conversation_messages(session_id,id);
    create index workflow_conversation_messages_identity_lookup on public.conversation_messages(actor_id,conversation_id,session_id,turn_id,id);
    for item in select * from pg_temp.workflow_chat_modes loop
      execute format('alter table %s %s trigger %I',item.table_oid::regclass,case item.enabled when 'D' then 'disable' when 'R' then 'enable replica' when 'A' then 'enable always' else 'enable' end,item.trigger_name);
    end loop;
    create trigger workflow_chat_guard before insert or update on public.conversations for each row execute function nexus_private.workflow_chat_guard();
    create trigger workflow_chat_guard before insert or update on public.conversation_messages for each row execute function nexus_private.workflow_chat_guard();
  elsif exists(select 1 from pg_temp.workflow_chat_manifest m left join pg_catalog.pg_trigger t
    on t.tgrelid=format('public.%I',m.table_name)::regclass and t.tgname='workflow_chat_guard'
    where t.oid is null or t.tgenabled not in('O','A')) then raise exception 'Workflow conversation installed body guard is missing' using errcode='23514';
  end if;
  for item in select * from (values
    ('wf_conversation_messages_turn_id_lookup',array['turn_id','id']),
    ('wf_conversation_messages_session_id_lookup',array['session_id','id']),
    ('workflow_conversation_messages_identity_lookup',array['actor_id','conversation_id','session_id','turn_id','id'])
  ) expected(index_name,fields) loop
    if not exists(select 1 from pg_catalog.pg_index i join pg_catalog.pg_class c on c.oid=i.indexrelid
      where i.indrelid='public.conversation_messages'::regclass and c.relname=item.index_name
        and i.indisvalid and i.indisready and not i.indisunique and i.indpred is null and i.indexprs is null
        and i.indnkeyatts=i.indnatts and (select array_agg(a.attname::text order by k.position)
          from unnest(i.indkey) with ordinality k(attnum,position) join pg_catalog.pg_attribute a
            on a.attrelid=i.indrelid and a.attnum=k.attnum)=item.fields) then
      raise exception 'Workflow conversation native lookup is incompatible' using errcode='23514';
    end if;
  end loop;
  for item in select table_name from pg_temp.workflow_chat_manifest loop
    execute format('select exists((select id,payload::text,row_version from public.%I except select id,body_text,row_version from pg_temp.workflow_chat_rows where table_name=$1) union all (select id,body_text,row_version from pg_temp.workflow_chat_rows where table_name=$1 except select id,payload::text,row_version from public.%I))',item.table_name,item.table_name) into changed using item.table_name;
    if changed then raise exception 'Workflow conversation changed historical bodies or versions' using errcode='23514'; end if;
    execute format('select exists(select 1 from pg_temp.workflow_chat_rows s join public.%I c on c.id=s.id cross join lateral jsonb_each(s.original_columns) old_column where s.table_name=$1 and to_jsonb(c)->old_column.key is distinct from old_column.value)',item.table_name) into changed using item.table_name;
    if changed then raise exception 'Workflow conversation changed an existing native projection' using errcode='23514'; end if;
  end loop;
  if (select to_jsonb(a)::text from public.appmeta a where singleton=1) is distinct from saved_meta
    or (select coalesce(string_agg(id||':'||definition_digest,E'\n' order by id),'') from nexus_private.workflow_projection_migrations) is distinct from saved_ledger
    or exists(select 1 from pg_temp.workflow_chat_modes s left join pg_catalog.pg_trigger t on t.tgrelid=s.table_oid and t.tgname=s.trigger_name where t.oid is null or t.tgenabled is distinct from s.enabled) then
    raise exception 'Workflow conversation changed application revision, ledger history or trigger modes' using errcode='23514';
  end if;
  if installed_digest is null then insert into nexus_private.workflow_projection_migrations values('202610040001_workflow_conversation_persistence',step_digest); end if;
end $forward$;
set constraints all immediate;
revoke all on function nexus_private.workflow_chat_instant(jsonb),nexus_private.workflow_chat_analysis(jsonb),
  nexus_private.workflow_chat_scope(jsonb),nexus_private.workflow_chat_body_valid(text,jsonb,jsonb),nexus_private.workflow_chat_guard()
  from public,anon,authenticated,service_role;
commit;
